function external_new_window(){for(let c=document.getElementsByTagName("a"),a=0;a<c.length;a++){let b=c[a];b.getAttribute("href")&&b.host!==location.host&&(b.target="_blank",b.rel="noopener")}}function pdf_new_window(){if(!document.getElementsByTagName)return!1;const e=[".pdf",".doc",".docx",".json",".xls",".xlsx",".ppt",".pptx",".zip",".rar",".tar",".gz",".7z",".bz2",".xz",".tgz",".tar.gz"];let t=document.getElementsByTagName("a");for(let n=0;n<t.length;n++){let o=t[n].href.toLowerCase();e.some(e=>o.endsWith(e))&&(t[n].onclick=function(){return window.open(this.href),!1})}}function apply_rules(){external_new_window(),pdf_new_window()}"undefined"!=typeof document$?document$.subscribe(function(){apply_rules()}):document.addEventListener("DOMContentLoaded",function(){apply_rules()});
